const body = $json.body || $json;
const event = body.event;
const number = body.request_number;
const payload = body.payload || {};

let nextEvent = event;
let nextPayload = {};

if (event === 'REQUEST_SUBMITTED') {
  nextEvent = 'QUOTATION_READY';
  nextPayload = {
    odoo_partner_id: 'ODOO-PENDING',
    odoo_quotation_id: 'Q-' + number,
    ai_analysis: {
      services: ['identity', 'digital'],
      departments: ['brand', 'finance']
    }
  };
}

if (event === 'PAYMENT_CONFIRMED') {
  nextEvent = 'TASKS_READY';
  nextPayload = {
    briefs: [
      { department: 'brand', brief: payload.title || 'Brand execution', clickup_task_id: null },
      { department: 'finance', brief: 'Track invoice and delivery', clickup_task_id: null }
    ]
  };
}

return [{ json: { event: nextEvent, request_number: number, payload: nextPayload } }];
